import{_ as e,c as i,o as t,a3 as s}from"./chunks/framework.CoV49S2T.js";const u=JSON.parse('{"title":"プライバシーの選択肢","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/privacy-choices.md","filePath":"ja/guide/privacy-choices.md","lastUpdated":1786595765000}'),r={name:"ja/guide/privacy-choices.md"};function o(l,a,h,n,c,d){return t(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="プライバシーの選択肢" tabindex="-1">プライバシーの選択肢 <a class="header-anchor" href="#プライバシーの選択肢" aria-label="Permalink to &quot;プライバシーの選択肢&quot;">​</a></h1><p>ClipboardxAI はローカルファーストのアプリケーションです。データはお客様のデバイスに留まるため、私たちが個人情報を収集・販売・共有することはありません。</p><h2 id="ローカルに保持するデータ" tabindex="-1">ローカルに保持するデータ <a class="header-anchor" href="#ローカルに保持するデータ" aria-label="Permalink to &quot;ローカルに保持するデータ&quot;">​</a></h2><p>ClipboardxAI はすべてのデータをお客様の Mac にローカルに保存します。</p><ul><li>クリップボード履歴とアプリの設定</li><li>カスタムアクションと設定</li><li>API key（Keychain 内、クラウドプロバイダーを設定した場合のみ）</li><li>デバッグログ（有効な場合）</li></ul><p>これらのデータがアプリ自身によってサーバーへアップロードされることはありません。</p><h2 id="クラウド-ai-のオプトイン" tabindex="-1">クラウド AI のオプトイン <a class="header-anchor" href="#クラウド-ai-のオプトイン" aria-label="Permalink to &quot;クラウド AI のオプトイン&quot;">​</a></h2><p>クラウド AI 機能は<strong>既定でオフ</strong>です。コンテンツが送信されるのは、お客様が選んだプロバイダーに、ご自身の API key を使って、かつクラウドアクションを実行したときだけです。設定済みのプロバイダーは <strong>設定 → AI</strong> で確認または削除できます。</p><h2 id="お客様の権利" tabindex="-1">お客様の権利 <a class="header-anchor" href="#お客様の権利" aria-label="Permalink to &quot;お客様の権利&quot;">​</a></h2><p>ClipboardxAI はサーバー上に個人データを収集・保存しないため、私たちがアクセス・削除・移転すべき個人データは存在しません。すべてのデータは、アプリ内で直接管理するか、アプリのコンテナフォルダーを削除することで管理できます。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard</span></span></code></pre></div><h2 id="販売しない" tabindex="-1">販売しない <a class="header-anchor" href="#販売しない" aria-label="Permalink to &quot;販売しない&quot;">​</a></h2><p>ClipboardxAI はいかなる個人情報も販売しません。種類を問わず、サードパーティのアナリティクス・広告・追跡サービスは使用していません。</p><h2 id="お問い合わせ" tabindex="-1">お問い合わせ <a class="header-anchor" href="#お問い合わせ" aria-label="Permalink to &quot;お問い合わせ&quot;">​</a></h2><p>プライバシーの選択肢についてご質問がある場合は、以下で issue を作成してください。 <code>https://github.com/clipboardxAI/clipboard-site/issues</code></p>',15)])])}const b=e(r,[["render",o]]);export{u as __pageData,b as default};
